INSERT INTO feature VALUES('world-migration','runtime','A migration running at its world in one process','located-judgements','implemented','unique','mainstream languages','`migrate [w] { t }` runs `t` on a thread and over a store of its own, closed over its captures, each crossed in by content through a chunk store of that crossing alone and the answer crossed back the same way, on both tiers; `hold v` runs to `v` and `let x at w = h ; t` binds `x` to it, a handle in one process being its content. A thunk the checker lets cross by its image runs at the caller, laid out at the site the caller''s function keeps for its body. A field the caller projects from a record a migration answers reads as it does in place, since the caller''s selections table every record head the program builds. A capture or answer that does not cross declines the run at the migration. A host whose world bindings bind the world to another process ships the migration there (migrate-wire).','core-sequent runtime-emitter','corpus/ledger/features/world-migration.gandr corpus/model/worlds/twice.gandr corpus/model/worlds/open.gandr corpus/model/worlds/seat-and-operator.gandr corpus/model/worlds/closure-axes.gandr crates/runtime-emitter/tests/world.rs','corpus/ledger/features/world-migration.gandr',NULL);
